css:
#shade { position:absolute; left:0; right:0; bottom:0; height:520px; background:linear-gradient(to top, rgba(0,0,0,.78), rgba(0,0,0,0)); opacity:0; }
#box { position:absolute; left:110px; bottom:120px; width:1500px; }
#tag { display:inline-block; background:var(--red); color:#fff; font-weight:700; font-size:34px; letter-spacing:.14em; padding:10px 22px 8px; transform-origin:left center; }
#title { font-weight:700; font-size:118px; line-height:1.02; margin-top:22px; text-transform:uppercase; text-shadow:0 6px 30px rgba(0,0,0,.55); }
#rule { height:8px; width:340px; background:var(--red); margin-top:26px; transform-origin:left center; }
#meta { font-weight:400; font-size:38px; margin-top:22px; opacity:.92; letter-spacing:.04em; }

js:
document.getElementById('title').textContent = V.title;
document.getElementById('meta').textContent = V.meta;
const D = V.duration;
tl.to('#shade', { opacity: 1, duration: 0.4 }, 0);
tl.fromTo('#tag', { scaleX: 0 }, { scaleX: 1, duration: 0.35, ease: 'power3.out' }, 0.1);
tl.fromTo('#title', { y: 60, opacity: 0 }, { y: 0, opacity: 1, duration: 0.55, ease: 'power3.out' }, 0.3);
tl.fromTo('#rule', { scaleX: 0 }, { scaleX: 1, duration: 0.5, ease: 'power2.out' }, 0.6);
tl.fromTo('#meta', { y: 24, opacity: 0 }, { y: 0, opacity: 0.92, duration: 0.45 }, 0.75);
tl.to('#box', { opacity: 0, y: -20, duration: 0.4, ease: 'power2.in' }, D - 0.45);
tl.to('#shade', { opacity: 0, duration: 0.45 }, D - 0.45);
